<div class="mx-auto max-w-4xl"><p class="text-sm font-bold text-indigo-600">PASO 3 · TUTOR IA</p><h1 class="mt-2 text-3xl font-extrabold">Tu apoyo para aprender, 24/7</h1><p class="mt-2 text-slate-500">Haz una pregunta concreta. El Tutor responde de forma breve para ayudarte a avanzar.</p><section class="mt-6 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm" x-data="tutorChat()"><div id="tutor-messages" class="h-[420px] space-y-4 overflow-y-auto p-5"><div class="max-w-xl rounded-2xl rounded-tl-sm bg-indigo-50 p-4 text-sm text-indigo-950">Hola, soy tu Tutor IA. ¿Qué estás aprendiendo hoy?</div>@foreach($conversation->messages as $message)<div class="flex {{ $message->role === 'user' ? 'justify-end' : '' }}"><div class="max-w-xl rounded-2xl p-4 text-sm {{ $message->role === 'user' ? 'rounded-tr-sm bg-indigo-600 text-white' : 'rounded-tl-sm bg-slate-100 text-slate-800' }}">{{ $message->content }}</div></div>@endforeach</div><form @submit.prevent="send" class="border-t border-slate-100 p-4"><div class="flex gap-3"><textarea x-model="message" required maxlength="600" rows="2" placeholder="Escribe tu pregunta..." class="flex-1 resize-none rounded-xl border-slate-200 focus:border-indigo-500 focus:ring-indigo-500"></textarea><button :disabled="loading" class="rounded-xl bg-indigo-600 px-5 py-2.5 text-sm font-bold text-white disabled:opacity-50" x-text="loading ? 'Pensando...' : 'Enviar'"></button></div><p class="mt-2 text-right text-xs text-slate-400"><span x-text="message.length"></span>/600 caracteres</p></form></section></div>
<script>function tutorChat(){return{message:'',loading:false,async send(){if(!this.message.trim())return;let text=this.message;this.message='';document.querySelector('#tutor-messages').insertAdjacentHTML('beforeend',`<div class="flex justify-end"><div class="max-w-xl rounded-2xl rounded-tr-sm bg-indigo-600 p-4 text-sm text-white">${this.escape(text)}</div></div>`);this.loading=true;try{let r=await fetch('{{ route('adaptive.tutor.message') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({message:text})});let d=await r.json();document.querySelector('#tutor-messages').insertAdjacentHTML('beforeend',`<div class="max-w-xl rounded-2xl rounded-tl-sm bg-slate-100 p-4 text-sm text-slate-800">${this.escape(d.reply||'No pude responder.')}</div>`)}catch(e){alert('No se pudo enviar el mensaje.')}this.loading=false;this.$nextTick(()=>{let box=document.querySelector('#tutor-messages');box.scrollTop=box.scrollHeight})},escape(t){let d=document.createElement('div');d.textContent=t;return d.innerHTML}}}</script>
